) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Insert-only audit of master edits (R10.6) - nobody can change it, not even the owner.';

CREATE TABLE `approval_decision` (
  `approval_decision_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `approval_request_id` BIGINT UNSIGNED NOT NULL,
  `decision` VARCHAR(12) NOT NULL,
  `decision_channel` VARCHAR(16) NOT NULL DEFAULT 'in_app',
  `authority_delegation_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `decision_reason` VARCHAR(300) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`approval_decision_id`),
  UNIQUE KEY `uq_approval_decision_1` (`approval_request_id`),
  UNIQUE KEY `uq_approval_decision_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_approval_decision_approval_request` FOREIGN KEY (`approval_request_id`) REFERENCES `approval_request` (`approval_request_id`),
  CONSTRAINT `fk_approval_decision_authority_delegation` FOREIGN KEY (`authority_delegation_id`) REFERENCES `authority_delegation` (`authority_delegation_id`),
  CONSTRAINT `fk_approval_decision_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_approval_decision_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_approval_decision_1` CHECK (`decision` IN ('approved','rejected')),
  CONSTRAINT `ck_approval_decision_2` CHECK (`decision_channel` IN ('in_app','phone_remote')),
  CONSTRAINT `ck_approval_decision_3` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Checker side of maker-checker. One final decision per request.';

CREATE TABLE `message_outbox` (
  `message_outbox_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `message_type` VARCHAR(24) NOT NULL,
  `recipient_phone` VARCHAR(20) NOT NULL,
  `safe_template_key` VARCHAR(40) NOT NULL,
  `rendered_text` VARCHAR(500) NULL DEFAULT NULL,
  `family_link_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `payment_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `counter_sale_payment_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `due_promise_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`message_outbox_id`),
  UNIQUE KEY `uq_message_outbox_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_message_outbox_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_message_outbox_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_message_outbox_1` CHECK (`message_type` IN ('family_link','receipt','due_reminder','appointment_reminder','alert_notice')),
  CONSTRAINT `ck_message_outbox_2` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Simulated SMS/WhatsApp. rendered_text is an EXTENSION (CR-B2) so the screen can show the message.';

CREATE TABLE `alert_escalation` (
  `alert_escalation_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `alert_event_id` BIGINT UNSIGNED NOT NULL,
  `escalated_to_staff_id` BIGINT UNSIGNED NOT NULL,
  `reason` VARCHAR(300) NOT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`alert_escalation_id`),
  UNIQUE KEY `uq_alert_escalation_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_alert_escalation_alert_event` FOREIGN KEY (`alert_event_id`) REFERENCES `alert_event` (`alert_event_id`),
  CONSTRAINT `fk_alert_escalation_staff` FOREIGN KEY (`escalated_to_staff_id`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_alert_escalation_recorded_by` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_alert_escalation_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_alert_escalation_1` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Unanswered interrupt escalated to a backup person.';

CREATE TABLE `message_delivery_event` (
  `message_delivery_event_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `message_outbox_id` BIGINT UNSIGNED NOT NULL,
  `delivery_state` VARCHAR(18) NOT NULL,
  `details` VARCHAR(300) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`message_delivery_event_id`),
  UNIQUE KEY `uq_message_delivery_event_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_message_delivery_event_message_outbox` FOREIGN KEY (`message_outbox_id`) REFERENCES `message_outbox` (`message_outbox_id`),
  CONSTRAINT `fk_message_delivery_event_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_message_delivery_event_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_message_delivery_event_1` CHECK (`delivery_state` IN ('queued','simulated_sent','failed')),
  CONSTRAINT `ck_message_delivery_event_2` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Delivery state trail of an outbox message.';

